class multiset:

	def __init__(self):
		self.items = dict()
		self.len = 0

	def add(self, it):
		self.items[it] = self.items.get(it, 0) + 1
		self.len += 1

	def remove(self, it):
		it_value = self.items.get(it, 1) - 1
		if it_value == 0:
			self.items.__delitem__(it)
		else:
			self.items[it] = it_value
		self.len -= 1

	def pop(self):
		it = next(iter(self.items.keys()))
		self.remove(it)
		return it

	def __len__(self):
		return self.len

	def __str__(self):
		return str(self.items)
import sys
fd = sys.stdin
n = int(fd.readline())
bp = [int(i) for i in fd.readline().split()]
cp = [int(i) for i in fd.readline().split()]
for i in range(n - 1):
	if bp[i] > cp[i]:
		print(-1)
		sys.exit()
map_value = dict()
count = 0
for i in bp + cp:
	if i not in map_value:
		map_value[i] = count
		count += 1
E = [multiset() for i in range(count)]
for i in range(n - 1):
	(a, b) = (map_value[bp[i]], map_value[cp[i]])
	E[a].add(b)
	E[b].add(a)
odd_vert = []
for i in range(count):
	if len(E[i]) % 2 == 1:
		odd_vert.append(i)
first_vert = 0
if len(odd_vert) == 2:
	first_vert = count
	E.append(multiset())
	E[count].add(odd_vert[0])
	E[odd_vert[0]].add(count)
	E[count].add(odd_vert[1])
	E[odd_vert[1]].add(count)
elif len(odd_vert) != 0:
	print(-1)
	sys.exit()
stack = [first_vert]
sol = []
while stack:
	v = stack[-1]
	if len(E[v]) == 0:
		sol.append(v)
		stack.pop()
	else:
		u = E[v].pop()
		E[u].remove(v)
		stack.append(u)
inv_map_value = {v: i for (i, v) in map_value.items()}
if sol[0] == count and len(sol) != n + 2:
	print(-1)
elif sol[0] == count:
	for i in range(1, len(sol) - 1):
		print(inv_map_value[sol[i]])
elif len(sol) != n:
	print(-1)
else:
	for i in sol:
		print(inv_map_value[i])
